    "lead": "터널 사고, 여관, 외할머니의 지도, 첫머리의 수기. 따로 굴러가던 이야기가 마지막 장에서 한 집안의 일로 묶입니다. 답의 대부분은 구리하라의 추리라는 것도 함께 기억해 두시길 권합니다.",
