      "type": "text",
      "text": "여관이 습격당한 밤, 폐촌의 구멍 속에서 묶인 야비쓰가 나옵니다. 검은 코트의 습격자는 여관 안주인 호이시미즈 가노입니다. 첫머리 수기를 쓴 오키가미 기미코의 딸입니다. 구리하라의 추리로는 옛 터널의 낙반도 사고가 아니었습니다. 기미코가 준에게 배운 측량과 마을 여자들의 돌 깎기 솜씨로 가짜 삼각점을 세워, 7도를 6도로 틀어 놓은 것입니다. 노린 대상은 여자들을 가둔 마을 남자들이었고, 준도 그때 함께 죽었다고 봅니다."
