      "text": "2030년 1월 26일 밤, 거렁바위골에 들어가 본 사람들의 머릿속 「씨앗」이 한꺼번에 식인 충동을 일으킵니다. 병원에서는 폭주한 지태성이 동생 지태오를 공격하고, 태오는 형을 화장실에 가둔 직후 숨집니다. 정민정은 면담하던 예나를 공격하다 지율에게 갇히고, 끝내 이성을 찾지 못해 사살됩니다. 기숙사에서는 최석진과 최서희까지 폭주합니다. 지휘를 맡은 강지철은 덮쳐 온 서희의 머리를 부수지 않고 탕비실에 가둡니다. 그리고 제 손목을 그어 폭주자 약 80명을 지하 통제실로 끌고 가 함께 갇힙니다. 윤성아도 그 밤에 죽습니다."
