   "plus": false,
   "gajebon": false,
   "genre": "소설",
   "deep": true,
   "slug": "폐놀이공원의-살인",
   "excerpt": "책은 1장을 다시 펴게 만듭니다 다 읽고 나서 1장으로 돌아가 봤습니다. 다 있더군요. 숨겨 놓은 게 아니라 그냥 펼쳐 놓았는데 제가 못 본 것이었습니다. 책은 약 400페이지이며, 프롤로그와 에필로그를 포함해 총 6개의 장으로 이루어져 있습니다. 프롤로그 1장 잃어버린 꿈의 나라 2장 인형탈을 쓰고 죽다 3장 불타는 미궁 4장 땅에 묻힌 진실 에필로그 장 제목만 봐도 이 책이 무엇을 하려는지 보입니다. 꿈의 나라로 시작해서 땅에 묻힌 진실로 끝납니다. 주인공은 마가미 에이타로로. 편의점 알바를 하며 폐허 블로그를 운영합니다. 이외 꽤 많은 등장 인물들이 나오지만 책 처음에 등장 인물 소개가 있어 좀 덜 헷갈립니다. 이야기는 이렇습니다",
