   "deep": false,
   "slug": "인버트",
   "excerpt": "영매탐정 조즈카의 후속작입니다. 🎉 사실 지난 작품에서 마지막에 너무 큰 걸 터트려서 후속작이 나오기 어려울 꺼라 생각했는데… 굉장한 작품이 나왔습니다. 😍 책은 약 480페이지 3가지 중단편으로 구성되어 있습니다. 1. 구름 위의 맑은 하늘 ☁️ 2. 포말의 심판 ⚖️ 3. 신용할 수 없는 목격자 👀 3가지 이야기가 모두 좋으며, 3번째 이야기는 특히 더 압도적으로 좋았습니다. 💯 이번 작품에서 주인공 조즈카의 캐릭터가 확실하게 자리 잡은 것으로 생각됩니다. 그리고 굉장히 매력적으로 묘사됩니다. ✨ 글인데도 캐릭터가 이렇게 매력적으로 눈에 보일 듯하게 묘사되는 건 독자의 입장에서는 정말 놀라운 경험입니다. 🤩 이야기는 이렇습니다.",
