   "deep": false,
   "slug": "아이는-무서운-꿈을-꾼다",
   "excerpt": "우사미 마코토의 신작입니다. ✨ 제목만 봐도 슬픔이 몰려오는군요 😢 이번에는 또 어떤 처절한 이야기일까요? 🤔 책은 약 410페이지 📖 7개의 챕터로 나누어져 있습니다, 1장 모든 것은 가을에 일어난 일 🍂 2장 밤에서 태어난 남자는 달빛에 형상화된다. 🌕 3장 기억은 때로 지독한 거짓말을 한다. 🌀 4장 완만한 삶은 완만한 죽음만큼 견디기 힘들다. 💔 5장 모든 것을 아는 것보다 슬픈 일은 없다. 😞 6장 피를 나눠 증오는 더 커진다. 🩸 7장 깨어나라 부르는 소리 있도다. 🔔 책은 주인공 와타루의 시점으로 진행되며, 이 책은 특수 설정 미스터리입니다.",
