   "deep": false,
   "slug": "은달이-뜨는-밤-죽기로-했다",
   "excerpt": "그때는 맞고 지금은 틀리다! 🤔 그때는 틀렸고 지금은 맞다! ✔️ 이건 성장 소설이군요! 🌱 책은 약 270페이지 📖 7개의 장으로 이루어져 있고, 책이 그리 두껍지 않아 후루룩 읽을 수 있는 책입니다. ✨ 1장 한밤의 티 파티 ☕ 2장 할머니의 맛 🍲 3장 오버 더 레인보우 🌈 4장 공백의 48분 ⏳ 5장 사과나무 꼭대기 🍏 6장 기자 구보 씨의 찰나 📰 7장 운수 좋은 날 🍀 앞서 말했지만 개인적인 느낌은 성장 소설입니다. 🌟 주인공이 자신의 이름을 찾아가는 과정이나, 점점 빵 기술(?)이 늘어나는 부분을 보면서 개인적인 느낌으로는 이 책은 성장 소설입니다.",
