   "genre": "소설",
   "deep": false,
   "slug": "가연물",
   "excerpt": "🚨 경찰소설입니다! 요네자와 호노부가 경찰소설을?! 😲 와, 대단합니다! 이 작가의 한계는 없는 것인가…🤔 📖 책은 약 330 페이지, 5개의 단편으로 구성되어 있습니다. 1. 낭떠러지 밑 2. 졸음 3. 목숨 빚 4. 가연물 5. 진짜인가 주인공은 가쓰라 경부로, 우직하고 자신의 일을 밀어부치는 타입의 경찰입니다. 🚔 모두가 “예쓰”라고 할 때, 아무렇지도 않게 “노”를 외치는 사람! 이 부분이 이 책의 핵심 재미 포인트입니다! 😄 1. 낭떠러지 밑 (⭐️⭐️⭐️⭐️) 산장 주인으로부터 스키 손님 4명이 연락이 되지 않는다는 신고가 접수됩니다. 🏔️ 수색 중, 낭떠러지 아래에서 1명이 사망하고 다른 한명은 중태로 발견됩니다.",
