   "slug": "죽음에-이르는-꽃",
   "excerpt": "한 가족에 대한 이야기 🏠 괴담보다 기담에 가까운 이야기 📖 하지만 뒤로 갈수록 소름 끼치는 이야기 😱 책은 약 390페이지, 7가지의 이야기로 되어 있습니다. 📚 1. 결산의 관 ⚰️ 2. 선택의 상자 📦 3. 귀환의 항아리 🏺 4. 분노의 돌 💢 5. 황금잔 🥇 6. 천부의 재능 🎨 7. 무결의 인간 👤 사실 마지막 이야기는 총집합 편에 가까우므로 실제는 6가지 이야기로 볼 수 있습니다. 🤔 미쓰다 신조의 후예라는 말이 있던데, 개인적으로 이야기의 결이 다르다고 생각합니다. 💭 미쓰다",
