   "excerpt": "역시 후루타덴 유닛의 이야기의 밀도는 최고입니다. 🔗 그리고... 이 이야기는 처절함의 끝판왕입니다. 😢 📚 책은 약 400페이지로, 1부와 2부로 나누어져 있습니다. 1️⃣ 1부: 등장인물들의 어린 시절과 사건이 발생하는 부분 🧸 2️⃣ 2부: 그들이 어른이 되고 난 후의 이야기 🕰️ 📌 이 책의 주요 인물은 아사히, 유히, 그리고 미오리입니다. 이 세 인물은 각자 자신보다 서로를 위한 마음으로 이야기가 꼬여갑니다. 💔 서로를 위했지만 비극적인 결말로 향해 달려가는... 제가 읽어본 책 중 가장 처절한 이야기가 아닐까 싶습니다.",
