   "excerpt": "✍️ 우케쓰 | 📚 리드비 | 🗓️ 출간: 2025년 2월 🏡 \"일상 속에서 서서히 스며드는 공포… 『이상한 집 2』!\" 📌 완벽한 서술 트릭과 치밀한 구성! 📖 이야기가 확장될수록 더욱 빠져드는 몰입감! 📌 480페이지, 11개의 작은 이야기 + 구리하라의 추리로 마무리 📜 각각의 단편이 시각적 도면과 함께 제공되어 더욱 실감나는 몰입감! 📌 작은 이야기들이 점점 연결되면서 거대한 서사를 형성! 📢 \"작은 단서들이 모여 거대한 진실을 만든다!\" 🎭 이야기의 전개 🏡 집이라는 가장 익숙한 공간에서 시작되는 불길한 이야기들… 🔍 처음에는 별개의 이야기 같지만, 읽을수록 하나의 거대한 퍼즐이 맞춰진다!",
