   "excerpt": "✍️ 김영민 | 🏷️ 아프로스미디어 | 🗓️ 2025년 3월 출간 ________________________________________ 🔍 클로즈드 서클 ✖ 밀실 살인 ✖ 본격 미스터리 …어? 그런데 한국 미스터리입니다! 🇰🇷 📚 책 정보 • 약 290페이지 • 프롤로그, 에필로그 제외 10장 구성 • 등장인물: 총 11명 • 주인공: 1인칭 시점의 ‘한규현’ (탐정 역할!) • 전체적으로 빠르게 읽히는 편 🎯 줄거리 요약 지구온난화로 바닷속에 잠길 미래를 대비한 수상탑. 그곳에 초대된 11명의 사람들. 그리고 어느 날, 폭우와 함께 터지는 보트 폭파, 정전과 밀실 속 살인 사건.",
