   "excerpt": "\"다시 읽었는데도 무서웠다.\" \"한 장 한 장 넘길 때마다 뱀이 몸을 감는 듯한 섬뜩함.\" \"이래서 이 책을 ‘현실 공포소설의 정점’이라 부르는구나.\" 🧱 공포소설 + 본격 미스터리의 완벽한 결합 미쓰다 신조의 ‘집 시리즈’의 첫 작품 『흉가』는 단순한 ‘무서운 이야기’를 넘어서는 구조적 완성도, 설정의 정교함, 그리고 페이지를 덮은 뒤에도 사라지지 않는 잔상으로 📌 “가장 무서운 미스터리” 중 하나로 손꼽히는 작품입니다. 이 책은 단지 공포를 소비하는 이야기 그 이상입니다.",
