   "excerpt": "“대항해 시대의 그 군함이, 클로즈드 서클 미스터리로 돌아왔다.” 거친 파도 위, 폐쇄된 공간. 그리고 연쇄 살인. 📚 약 410페이지, 에필로그 제외 총 4장으로 구성된 이 작품은 ‘범선 군함’이라는 굉장히 신선한 배경을 중심으로 밀실 살인과 클로즈드 서클을 엮어낸 미스터리입니다. 이야기의 시점은 구두장이 출신 수병 ‘네빌’. 곧 태어날 아이를 임신하고 있는 사랑하는 아내를 두고 우연히 술집에서 강제 징집되어 범선 군함 ‘헐버트호’에 탑승하게 됩니다. 그리고 그곳에서 첫 번째 살인이, 곧이어 두 번째 살인이 발생합니다. 문제는, 매번 사건 현장 근처에 네빌이 있다는 점. 그는 과연 억울한 희생자인가, 아니면…?",
