   "excerpt": "와… 역시 사람들이 명작이라 말하는 이유가 있군요. 읽는 내내 숨이 막힐 만큼 치밀하고 묵직한 이야기였습니다. ⚖️🔥 📖 책 소개 이 책은 약 410페이지로, 프롤로그와 에필로그를 포함해 총 6장으로 구성되어 있습니다. • 제1장 사회 복귀 • 제2장 사건 • 제3장 조사 • 제4장 과거 • 제5장 증거 • 제6장 피고인을 사형에 처함 • 에필로그 두 사람이 한 일 주요 인물은 • 사형 집행을 두 번 담당했던 前 교정관 난고 🧑 • 과실치사 전과로 복역 후 가석방된 청년 미카미 준이치 👤 📌 줄거리 난고는 교도관으로 지내면서 평생 마음속에 사형이라는 무거운 그림자를 안고 살아왔습니다.",
