   "excerpt": "“밀실을 수집하는 자가 있습니다. 그가 원하는 건 범인의 목숨이 아니라, 오직 ‘밀실의 해답’뿐.” 인친님들, 이 탐정… 사람이 맞긴 한 걸까요? 👻🚪 📚 책 정보 약 320쪽 / 5편의 단편으로 꽉 채워져 있습니다. 이야기의 배경은 1937년부터 2001년까지 흐르지만, 우리의 주인공 ‘밀실수집가’는 늙지 않습니다. 시공간을 초월해 오직 ‘밀실 살인’이 일어난 곳에만 스윽- 나타나서 사건을 해결하고 사라집니다. (약간 도깨비? 요정? 느낌 🧞‍♂️) 🧩 이야기 (The Collection) 총 5개의 기묘한 밀실 사건이 펼쳐집니다. 1. 버드나무 정원 (1937년) ⭐⭐⭐ 학교 당직실, 음악 교사가 살해당했습니다.",
