   "excerpt": "“전작에 이어 2번째 시리즈. 소재는 여전히 신선한데… 인물들은 아직 멋이 안 붙었다.” 😅 📚 책 정보 약 340쪽 / 5개의 장 1장 해결편 2장 X의 비극 3장 흑사장 살인사건 4장 Death on the Nile 5장 그리고, 미궁에 빠지다 이 시리즈의 기본 설정은 하나입니다. 전 세계 부자들에게 ‘탐정 유희’를 제공한다. 다만, 이 게임에서 사람은 진짜로 죽는다… 💀 🧩 이야기 외딴 섬 저택, 일명 바스커빌관. 이번에도 탐정 유희를 즐기려는 이들이 이곳에 모입니다. 구성은 • ‘탐정’ 역할의 참가자들 • 연기와 진행을 맡는 ‘캐스터’ • 뒤에서 전체를 조율하는 스태프들 스태프는 게임이 끝날 때까지 모습을 드러내지 않습니다.",
