   "excerpt": "🚢 우먼 인 캐빈 10 | 루스 웨어 | 필름 | 2025년 09월 “우먼 인 캐빈 시리즈 10권이 아니라 ‘10호 선실의 여자’였습니다—착각한 사람… 저 말고도 있죠? 😅” 📖 책 소개 • 분량: 약 460쪽 | 구성: 36개의 짧은 챕터 • 시점: 기자 로라(로) 블랙록 1인칭 중심 • 무대: 초호화 크루즈 오로라호 • 등장인물 가이드가 따로 있을 정도로 인물이 많지만, 챕터가 짧아 리듬감은 훌륭합니다. ⏱️ 🧩 줄거리 잡지사 벨로시티 기자 로는 상사 대타로 오로라호 취재에 탑승합니다. 문제는 출발 직전 자택 침입 강도 사건을 겪었다는 것. 그 트라우마와 수면제·항불안제에 의존하는 상태에서 배에 오릅니다.",
   "pages": 464,
