   "aladin": "https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=372260462&partner=openAPI&start=api",
   "rating": 2,
   "plus": false,
   "gajebon": false,
   "genre": "소설",
   "deep": false,
   "slug": "일곱-번째는-내가-아니다",
   "excerpt": "😶‍🌫️ 음… 아… 음… 글톤이 저랑 너무 안 맞았어요… 몰입도는 분명 높은데, 읽는 내내 자꾸만 벽이 느껴지는 책이었습니다. 📚 책 정보 약 450페이지, 에필로그 제외 총 52장으로 구성 주로 ‘조’의 시점에서 진행되며, 중간에 조를 짝사랑하는 ‘샐리’의 시점이 더해집니다. 🩸 줄거리 뉴질랜드의 도시 크라이스트처치. 이곳에서 연쇄살인이 벌어지고 있습니다. 범인은 경찰서 청소부 ‘조’. 그는 일부러 모자란 척하며 수사 정보를 수집하고, 살인을 이어갑니다. 하지만 일곱 번째 살인은… 그가 한 게 아닙니다. “이 지역의 유일한 살인자는 나여야 해.” 조는 자신의 자부심을 지키기 위해 모방범을 찾아 나섭니다.",
