   "deep": false,
   "slug": "피안장의-유령",
   "excerpt": "초능력 설정인데도 끝까지 정통 미스터리로 밀어붙이는 영리한 추리 소설 🤯 폐쇄된 별장, 초능력자들, 의자 속 시체… 끝까지 “능력이냐 트릭이냐” 고민하게 만드는 타입 👻",
