   "cover": "covers/a1c6b2939e.jpg",
   "publisher": "블루홀식스(블루홀6)",
   "aladin": "https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=376782757&partner=openAPI&start=api",
   "rating": 4,
   "plus": false,
   "gajebon": false,
   "genre": "소설",
   "deep": false,
   "slug": "꿈-전달",
   "excerpt": "“직접적으로 ‘보여주지’ 않는데, 끝나고 나서야 서서히 올라오는 소름…” 😨 극한의 아픔을 이야기로 풀어내던 작가의, 호러 단편집 버전 우사미 마코토입니다. 📚 책 정보 & 분위기 약 400페이지, 11편 단편 수록. 점프 스케어❌ → 서서히 스며드는 공포 + 기분 나쁜 잔상 타입의 호러 ✅ 11편 모두 결이 달라서 완벽하게 취향 저격인 작품만 있는 건 아니지만, 한 권에서 다양한 분위기의 호러를 맛볼 수 있다는 게 가장 큰 장점입니다 💀 🧩 수록 단편 1️⃣ 꿈 전달 ⭐⭐⭐ 더 이상 글을 쓸 수 없다고 말하는 천재 작가와 편집자. → “창작의 대가로 무엇을 내놓을 것인가”를 묻는 서늘한 오프닝.",
