   "genre": "소설",
   "deep": false,
   "slug": "대리모",
   "excerpt": "“뻔한데 왜 손에서 놓질 못하겠지? 머리로는 다 알면서도 가슴은 이미 다음 페이지를 넘기고 있는, 마성의 '월간 프리다 맥파든'입니다.” 결말이 훤히 내다보이는 클리셰 속에서도 기어코 우리의 심박수를 끌어올리고야 마는, 미친 몰입감을 가진 작가의 전형적인 팝콘 소설입니다. 🍿🌪️ 📚 책 정보 약 340쪽 / 프롤로그와 에필로그를 제외하고 총 41개의 챕터로 구성되어 있습니다. 특유의 짧고 속도감 넘치는 호흡 덕분에 가독성은 의심할 여지가 없습니다. 한 번 페이지를 펼치면 어느새 마지막 장을 덮고 있는 자신을 발견하게 되는, 흡입력 하나만큼은 타의 추종을 불허하는 작품입니다.",
