   "deep": false,
   "slug": "독이-든-화형-법정",
   "excerpt": "가벼운 라이트 노벨인 줄 알고 방심하며 펼치면 안됩니다! 마음의 준비 단단히 하셔야 할 겁니다. 어마어마한 난이도의 두뇌 싸움이 시작됩니다! 🤯🔥 📚 책 정보 약 570쪽 / 큰 사건의 흐름에 따라 총 3개의 챕터로 나뉘어 있습니다. 분량 자체가 상당한 이른바 '작은 벽돌책'입니다. 게다가 세계관과 인물 관계가 꽤 복잡하게 얽혀 있어서, 팝콘 무비처럼 훌훌 넘기기보다는 펜을 들고 꼼꼼하게 기록하며 읽어야 하는 고난도 작품입니다. 🧱✍️ 🧩 이야기 (The Story) 이곳은 마법을 구사하는 범죄를 일반 법으로 심판할 수 없는 세계입니다. 화형법정에서 마녀임이 증명되는 순간, 자비 없이 불태워집니다. 마녀를 증명하는 규칙은 3가지입니다.",
