   "genre": "소설",
   "deep": false,
   "slug": "금기의-아이",
   "excerpt": "“응급실에 실려 온 싸늘한 시신, 그런데 그 얼굴이... 저와 완벽하게 똑같이 생겼다면 어떨까요?” 또 한 명의 괴물 같은 '의사 출신 미스터리 작가'의 탄생을 알리는 강렬한 데뷔작입니다. 🩺❄️ 📚 책 정보 약 400쪽 / 총 6개의 장(발단, 연쇄, 밀실, 분수, 진실, 하루살이)으로 구성되어 있습니다. 데뷔 작가의 날것 같은 패기와 함께, 의사라는 직업적 전문성에서 비롯된 꼼꼼하고 완벽주의적인 성격이 이야기에 녹아 있는 미스터리입니다. 🏥📖 🧩 이야기 응급의학과 전문의 다케다 와타루에게 구급 12 로 실려 온 응급환자는 안타깝게도 이미 사망한 상태였습니다.",
