   "genre": "소설",
   "deep": false,
   "slug": "어려운-문제가-가득한-레스토랑",
   "excerpt": "이 책 이렇게 힙해도 되는 건가요? 한국 영화 3대 등장 씬에 버금가는, 치명적으로 매력적인 셰프 탐정의 등장입니다!” 😎✨ 낡고 식상할 수 있는 안락의자 탐정 포맷을 요즘 시대에 맞게 완벽히 세공해 낸, 트렌디함이 뚝뚝 흘러넘치는 소설입니다. 📚 책 정보 약 400쪽 / 총 6개의 단편으로 이루어진 연작 미스터리입니다. 배달 전문 고스트 레스토랑이라는 배경에 전개도 빠르고 가독성이 엄청납니다. 무거운 벽돌책들 사이에서 기분 좋게 리프레시하며 읽기 딱 좋은 분량과 속도감을 자랑합니다. 🛵💨 🧩 이야기 배달 앱에서 일반인이라면 절대 고르지 않을 기괴한 메뉴 조합을 주문하는 것.",
