   "author": "미나토 가나에",
   "cover": "covers/22b1ccdb7d.jpg",
   "publisher": "북홀릭(bookholic)",
   "aladin": "https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=268376015&partner=openAPI&start=api",
   "rating": 5,
   "plus": false,
   "gajebon": false,
   "genre": "소설",
   "deep": false,
   "slug": "속죄",
   "excerpt": "“과연 인간의 죄는 어디에서 시작되어, 어떻게 끝을 맺는가?” 미나토 가나에의 대표작인 <고백>과 감히 견줄 만한, 엄청나게 치밀한 구성을 자랑하는 작품입니다! 📚 책 정보 약 320쪽 분량의 이 책은 총 6개의 장으로 나뉘어 있습니다. • 각 장은 사건에 휘말린 주요 인물들의 시점으로 전개되며, 마지막 '속죄' 장에 이르러 흩어졌던 모든 퍼즐 조각이 소름 돋게 하나로 맞춰지는 구조를 취하고 있습니다. • 프랑스 인형 (사에), 학부모 임시총회 (마카), 곰 남매 (아키코), 열 달 열흘 (유카), 속죄 (아사코), 그리고 종장으로 구성되어 있습니다. 🧩 이야기 공기 좋은 시골 마을로 전학 온 도시 소녀 에미리.",
   "pages": 320,
