   "cover": "covers/d89a026448.jpg",
   "publisher": "북다",
   "aladin": "https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=392626367&partner=openAPI&start=api",
   "rating": 3,
   "plus": false,
   "gajebon": false,
   "genre": "소설",
   "deep": false,
   "slug": "스와이프-엄금",
   "excerpt": "“오른쪽 페이지는 스마트폰 화면, 왼쪽은 텍스트. 책을 스와이프하시겠습니까?” 내 스마트폰이 가장 소름 끼치는 살인 현장으로 변하는, 단 30분이면 완독 가능한 신개념 미스터리입니다. 📱🩸 📚 책 정보 전체 페이지는 약 134쪽 스마트폰보다 조금 더 큰 사이즈입니다. 책을 펼치면 오른쪽 페이지에는 '스마트폰 화면'이, 왼쪽 페이지에는 그에 대한 '상황 설명'이 나오는 아주 파격적이고 독특한 포맷을 취하고 있습니다. 시각적 몰입감이 엄청나서 문자 그대로 순식간에 읽어 치울 수 있습니다. 💨📖 🧩 이야기 주인공이 휴대폰 전원을 켜자마자 쏟아지는 여자친구의 메시지, 그리고 오컬트 전문 기자인 동아리 선배의 짜증 섞인 독촉장.",
