   "excerpt": "“제목 그대로… 시체가 주 소재입니다.” 근데 이걸 이렇게까지 ‘본격 미스터리’로 굴린다고요? 🤯 이런 발상 자체가 이미 한 방 먹이고 시작합니다. 📚 책 정보 약 420쪽 / 4개의 단편 수록. 대부분의 단편이 꽤 높은 수준이고, 개인적으로는 2편을 제외하고 전부 크게 만족했어요. 표지가 워낙 강렬해서(?) 처음엔 “이거 고어로 가는 거 아닌가…” 싶었는데, 막상 읽어보면 의외로 거부감이 크지 않습니다. 소재는 시체지만, 내용은 끝까지 본격 미스터리 쪽으로 붙어 있거든요 🔍 🧩 수록 단편 1) 본격 오브 더 리빙 데드 ⭐⭐⭐⭐⭐ J대 소프트테니스 동아리가 피서 여행을 떠나고, 저녁 분위기가 무르익던 순간 좀비 습격이 벌어집니다.",
