   "slug": "당신이-누군가를-죽였다",
   "excerpt": "가가 형사 시리즈의 12번째 작품입니다! 🎉 작가의 101번째 작품이라 그런지, 정말 힘을 주고 쓴 느낌이 물씬 느껴집니다! 그런데 라플라스 시리즈 “마녀와의 7일” 을 100번째 작품이라고 광고했는데... 101번째 작품이라고 띠지에 적는 건 뭔가 견제인 걸까요? 😂 핫핫! 책은 약 430페이지, 24개의 작은 챕터로 구성되어 있습니다. 📚 종이가 두꺼워서인지 페이지 수에 비해 굉장히 두껍게 보이고, 양장본이라 웅장한 느낌이 듭니다. 👑 정석적인 본격 미스터리의 길을 따라가며, 등장 인물도 그리 많지 않고, 가가 형사가 끊임없이 설명해 주기 때문에 내용이 어렵거나 헷갈리는 부분이 거의 없습니다.",
