   "slug": "고비키초의-복수",
   "excerpt": "🔗 연결될 것 같지 않은 이야기들이 연결될 때, 🔍 그 이야기가 감추어진 것이 많을 때, 아... 아름답다? 😮 📖 이 책은 약 380페이지, 총 6개의 막으로 구성되어 있습니다: 1️⃣ 제1막: 극장 찻집 2️⃣ 제2막: 연습장 3️⃣ 제3막: 의상방 4️⃣ 제4막: 쪽방 5️⃣ 제5막: 관람석 6️⃣ 종막: 고향 저택 📚❗ 이 책은 꽤 독특한 구성을 가지고 있습니다. 책의 제목처럼 기쿠노스케가 사쿠베에의 머리를 잘라 복수를 완성하고 난 뒤, 그의 지인 소이치로가 사건에 대해 사람들을 조사하는 방식으로 이야기가 진행됩니다.",
