   "country_fixed": "일본",
   "deep": false,
   "slug": "세뇌살인",
   "excerpt": "그 말로만 듣던 그 작품의 개정판이 드디어 나왔습니다! 😲 어마무시하다던 짐승의 성! 참 여기서 “성”은 캐슬이라는 뜻이입니다. 🏰 책은 약 360페이지로, 26개의 챕터로 이루어져 있습니다. 📚 페이지당 글자 수가 상대적으로 많아 체감상 450페이지 정도의 두께로 느껴집니다. 🤯 이 책은 실제 있었던 사건인 “기타큐슈 일가족 감금 살인사건”을 각색해서 만든 작품입니다. 개인적으로 실제 사건 각색의 최고봉은 시라이 도모유키의 명탐정의 제물이라고 생각하지만, 이 책도 굉장한 책임에 분명합니다. 👍 사실 짐승의 성은 읽기 어렵다는 말들이 많아 지금까지 미뤄왔던 것도 사실입니다.",
