   "excerpt": "🌟 유키하루오의 성서 시리즈 두 번째 작품입니다! 이 작가의 아이디어는 정말 놀라움 그 자체입니다 😲. 책은 약 340페이지로, 프롤로그를 제외하고 총 5개의 장으로 이루어져 있습니다 1️⃣ 에다우치지마섬 2️⃣ 십계 3️⃣ 시체와 발자국 4️⃣ 증거 인멸 5️⃣ 선택 총 9명의 등장인물이 있으며, 배경은 섬으로 한정됩니다 🌴. 이야기에 대한 당위성이 아주 잘 표현되어 있고, 이 부분이 시리즈의 핵심입니다. 물론 당위성의 방향이 우리의 예측과는 좀 다르다는 점이 놀라운 부분이죠 🤯. 책은 첫 장부터 강력한 인상을 주며 시작합니다. (이 부분은 책을 다 읽고 다시 보면 전혀 다른 의미로 다가옵니다.) 주요",
