   "slug": "법정유희",
   "excerpt": "유희란 의미는 사전적으로 즐겁게 놀고 장난함입니다. 😄 책 제목은 법정 게임이라는 의미로 해석 해야할 것 같군요 🤔 책은 약 420페이지로 2개의 챕터로 나누어져 있습니다. 📖 제1부 무고 게임 🎮 제2부 법정유희 ⚖ 1부는 케릭터 소개와 2부를 위한 빌드업으로 이루어져 있습니다 🛠 주인공은 구가 기요요시로 세이기로 불리우고 있습니다. 등장 인물로는 무고 게임에서 심판자 역할을 한 유키 가오루와 주인공과 함께 자라온 요리모토 미레이가 있습니다. 👨‍👩‍👧‍👦 각 챕터는 더 작은 챕터로 나누어져 있는데 책의 구성이 약간 아쉽습니다. 😕 이야기는 이렇습니다.",
