   "genre": "소설",
   "deep": false,
   "slug": "미로관의-살인",
   "excerpt": "관시리즈의 3번째 작품입니다. 이야..이 책한테 완전 취향 저격 당했습니다. 정말 엄청 나군요! 책은 약 370페이지로 책 속에 책이 있는 액자식 구성으로 이루어져 있습니다. 미로관의 살인 내 미로관의 살인 소설은 프롤로그 에필로그 제외 총 11개의 장으로 이루어져 있습니다. 이 책 내 소설은 표지와 차례 후기까지 완벽하게 책 처럼 구성되어 있습니다. 이 부분은 상당히 흥미롭습니다. 책의 내용은 이렇습니다. 시마다에게 책 한권이 도착했습니다. 제목은 미로관의 살인으로 실제 있었던 사건에 대한 소설입니다. 이 책의 작가 시시야 가도미는 개인적으로 알고 있고 그가 실제 사건에 관련되어 있어 책에 흥미를 느끼기 시작했습니다.",
