   "deep": false,
   "slug": "폭탄",
   "excerpt": "그가 돌아왔습니다 신작 폭탄을 가지고 말이죠! 역시나 역시군요! 책은 약 570페이지 에필로그 제외 총 3부로 나누어져 있으며, 결코 적은 분량은 아닙니다. 하지만 이게 뭔가요? 거의 시간이 순삭 되는 듯이 이야기에 몰입하여 읽게 됩니다. 꽤 많은 등장 인물들이 나오지만, 각 인물들의 케릭터성이 명확해서 헷갈리지 않고 강렬하게 다가옵니다. 1~3부는 각각 중심 인물이 다릅니다. 중심인물이 달라지니 글의 톤 또한 바뀌고 우리에게 다른 느낌을 주어 몰입감을 올립니다. 이거 완전 굉장합니다.. 이야기는 이렇습니다. 한 남성이 폭력으로 인해 경찰서에 연행되어 왔습니다.",
