   "slug": "키리고에-저택-살인사건",
   "excerpt": "앗 명탐정 김전일??? 아니지 김전일이 이런 스타일의 책을 따라 한거지… 책은 약 600페이지로 벽돌책에 가깝습니다. 프롤로그 에필로그 제외 총 7막으로 이루어져 있습니다 몰입도 높은 스토리로 많은 분량의 느낌은 들지 않습니다. 다만 등장인물이 그리 많은 편이 아닌데, 꽤 헷갈립니다. 이런 경우는 각 등장인물의 캐릭터성이 확실하지 않은 경우인데, 개인적인 느낌으로는 영상화를 염두하고 만든 이야기가 아닐까 싶습니다. 그래서 이야기 속에 캐릭터들도 외향적인 모습이 조금 강조됩니다. (이야기의 큰 사건을 봐도 느낄 수 있습니다.) 이야기는 이렇습니다.",
