   "aladin": "https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=318918490",
   "rating": 2,
   "plus": false,
   "gajebon": false,
   "genre": "소설",
   "deep": false,
   "slug": "나도라키의-머리",
   "excerpt": "히가 자매 시리즈의 4번째 작품이 출간되었습니다. 일본에서는 6번째 작품까지 출간되었다고 합니다. 하지만….사와무라 이치는 장편을 써야… 책은 약 270페이지 6개의 단편으로 이루어져 있습니다. 분량도 많고 단편의 특성상 금방 읽을 수 있습니다. 1. 5층 사무실에서 2. 학교는 죽음의 냄새 3. 술자리 잡담 4. 비명 5. 파인더 너머에 6. 나도라키의 머리 일단….전 히가 자매 시리즈를 무척 좋아합니다. 보기왕이 온다, 즈우노메 인형, 시시리바의 집까지 흥미롭게 읽은 시리즈입니다. 하지만 이 책은 술술 읽히지도 않고 읽다가 몇 번을 졸았는지 모르겠습니다. 심지어 단편집인데 말입니다. 아 너무 아쉽군요.",
