   "aladin": "https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=384368001",
   "rating": 4,
   "plus": false,
   "gajebon": false,
   "genre": "소설",
   "deep": false,
   "slug": "모성",
   "excerpt": "이야미스의 여왕의 책이 다시 우리에게 왔습니다 앗…그런데 신간이 아니라 개정판이군요! 책은 약 300페이지지만 판형이 약간 커서 각페이지당 글자수는 일반적인 책보다 많습니다 총 7개의 장으로 이루어져 있으며, 각 장은 “모성에 대하여” -> “어머니의 고백” -> “딸의 독백” 으로 이야기가 진행됩니다 제1장 엄숙한 시간 제2장 석상의 노래 제3장 탄식 제4장 오오 눈물로 가득한 사람아 제5장 눈물 항아리 제6장 오너라, 최후의 고통이여 제7장 사랑의 노래 각 장의 제목으로 각 장의 마지막 부분에 시가 포함되어 있습니다. 책은 교묘하게 우리를 기분 나쁜 감정이 들게 하고 이야기를 읽으면서 턱턱 걸리게 하는 부분을 만들어 놓았습니다.",
