   "plus": false,
   "gajebon": false,
   "genre": "소설",
   "deep": false,
   "slug": "더-케이지",
   "excerpt": "제목이 엄청나게 강렬합니다. 과연 내용도 강렬할까요? 짐승의 집이라니.. 책은 약 400페이지 프롤로그, 에필로그 제외 총 3개의 장으로 나누어져 있습니다 책의 판형이 조금 크고 페이지당 글자수가 많아 체감상 500페이지 이상 분량의 책입니다 1부 / 인터벌 /2부로 나누어져 있는데 각 파트 별 분위기가 조금 다릅니다. 1부가 사건이 시작되는 부분이고 2부는 반격(?)을 하는 부분이며, 인터벌은 그 중간 감옥에서 벌어지는 일입니다. 책의 주요 화자는 셰이 램버트와 잉그램 배넷입니다. 하지만 셰이 램버트에 조금 더 초점이 쏠려 있습니다. 아 그리고 더 케이지 짐승의 집이라는 제목은 직접적인 표현이 아니라 은유적인 문구입니다.",
