   "aladin": "https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=320896623",
   "rating": 4,
   "plus": false,
   "gajebon": false,
   "genre": "소설",
   "deep": false,
   "slug": "건널목의-유령",
   "excerpt": "11년 만의 신작이 나왔습니다. 초현실적인 부분과 미스터리적인 부분이 잘 어우러진 것 같아요 🕵️‍♂️✨ 책은 약 350페이지, 프롤로그와 에필로그를 제외하고 총 13장으로 이루어져 있습니다. 주요 화자는 신문사에서 퇴직하고 여성 잡지 기자로 일하고 있는 미쓰다입니다. 그의 시선으로 이야기가 진행됩니다 📖👀 오다와라 방면 건널목에서 유령이 출몰한다는 소문이 있습니다. 실제 기관차 운전자들이 유령을 사람으로 착각하고 기차를 세우는 경우가 종종 발생하고 있습니다. 미쓰다는 심령 현상에 대한 취재를 하던 중 이 건널목까지 도달하게 됩니다.",
