   "cover": "covers/9b8ba3fca9.jpg",
   "publisher": "빈페이지",
   "aladin": "https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=321295748",
   "rating": 3,
   "plus": false,
   "gajebon": false,
   "genre": "소설",
   "deep": false,
   "slug": "악어의-눈물",
   "excerpt": "악어의 눈물은 거짓 눈물 또는 위선적인 행위를 의미합니다. 표지의 아름다움과 더불어 이 책에 흐르는 전반적인 분위기입니다. 그리고 이 쫄깃함은..읽어보신 분들은 아시죠? 책은 약 400페이지 18개의 챕터로 나누어져 있습니다. 이야기는 시간 순으로 흘러가나 화자의 시점이 계속 변화합니다. 이렇게 변화하는 시점은 각 등장 인물 간의 내면을 100% 알기 어렵게 만들어주고 작가 특유의 심리묘사와 함께 어우러져 굉장한 긴장감을 만들어냅니다. 책의 내용은 이렇습니다 도키야 깃페이라는 노포 도자기점을 운영하는 가족이 있습니다. 부모님과 아들, 그의 아내, 그리고 손자까지 열심히 일하면서 그 가게를 꾸려 나가고 있었습니다.",
