   "deep": false,
   "slug": "하쿠바-산장-살인사건",
   "excerpt": "산장 시리즈의 마지막 (순서상으로는 아님) 으로 읽은 작품! 그런데…음….음….. 책은 약 370페이지 프롤로그, 에필로그 제외 총 7개의 장으로 이루어져 있습니다 1장 펜션 머더구스 2장 런던 브리지와 올드 머더구스의 방 3장 뿔 달린 마리아 4장 무너진 돌다리 5장 거위와 키다리 할아버지의 방 6장 마리아가 집에 돌아올 때 7장 잭과 질의 노래 책은 오빠를 이 산장에서 잃은 나오코와 그녀의 친구 마코토의 관점에서 진행됩니다. 전형적인 본격 미스터리의 공식을 잘 따르고 있습니다. 밀실에서 벌어진 살인과 그 살인을 밝히기 위해 단서를 모으는 주인공.",
