   "deep": false,
   "slug": "저택섬",
   "excerpt": "개그가 가미된 미스터리.. 이런 취향이군요!! 책은 약 360페이지 프롤로그 에필로그 제외 총 10장으로 구성되어 있습니다 제1장 저택으로 가는 먼 길 / 제2장 추락사건 이야기 / 제3장 나나에의 결단 / 제4장 전망실의 시체 / 제5장 전망실의 두 사람 / 제6장 알리바이 확인 / 제7장 다시 추락의 밤 / 제8장 주몬지 가즈오미의 스캔들 / 제9장 진범 / 제10장 진상 이 책을 지배하는 B 급 정서와 개그는 취향에 따라 책의 몰입도를 굉장히 올려주는 역할을 합니다. 그리고 책에서 등장하는 탐정인 고바야카와 사키는 아주 매력적이고 고혹적(?)으로 등장합니다. 주요",
