   "genre": "비소설",
   "deep": false,
   "slug": "꿰뚫는-한국사",
   "excerpt": "역사는 지루하다? 🤔 아닙니다. 제가 읽은 역사 책은 다 재미있었습니다. 🎉 책은 약 300페이지, 4개의 장, 14명의 인물 이야기로 구성되어 있습니다. 📖 이 책의 근간은 팟캐스트 방송 “역사 뇌피셜 그놈”에 있으며, 제가 개인적으로 애청하는 방송이기도 합니다. 🎧 역사라는 어쩌면 지루할 수도 있는 주제를 타고난 이야기꾼들이 풀어내는 굉장히 재미있는 책입니다. 😁 여기에 프로파일러 배상훈 교수님과 평론가 오창석님의 역사학자와는 다른 시선이 더해져서 독특한 톤을 만들어 내고 있습니다. 🕵️‍♂️👀 이 책에서 소개하고 있는 인물들은 우리에게 잘 알려진 인물들과 잘 알려지지 않은 인물들이 균형을 맞추고 있습니다.",
