   "plus": false,
   "gajebon": false,
   "genre": "소설",
   "deep": false,
   "slug": "I의-비극",
   "excerpt": "요즘 주가가 팍팍 오르는 작가죠! 🚀 요네자와 호노부의 사회파 미스터리입니다. 📚🔍 글의 스펙트럼이 얼마나 넓은 건지… 🌈✨ 책은 약 410페이지 서장 종장 제외 총 6개의 장으로 이루어져 있습니다. 💼 서장 : I의 비극 1장 가벼운 비 2장 얕은 저수지 3장 무거운 책 4장 검은 석쇠 5장 깊은 늪 6장 흰 불상 종장 I의 희극 각 장은 미노이시에 이주해온 사람들의 이야기로 에피소드 모음에 가깝습니다. 📖 주인공은 만간지와 간잔, 그리고 니시노 과장입니다. 주요 화자는 만간지이며, 그의 시점으로 이야기가 전개됩니다. 👥 이야기는 이렇습니다. 🏞️ 주민이 다",
