   "cover": "covers/07123a52c0.jpg",
   "publisher": "북다",
   "aladin": "https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=332928061",
   "rating": 5,
   "plus": false,
   "gajebon": false,
   "genre": "소설",
   "deep": false,
   "slug": "속임수의-섬",
   "excerpt": "저택섬의 후속작(?)입니다. 전편을 안 읽어도 큰 무리는 없으나… 읽으면 재미가 더해질 것은 사실입니다. 책은 약 480페이지 프롤로그, 에필로그 제외 총 13장으로 이루어져 있습니다. 작가의 다른 작품과 비슷하게 대사에 B급 감성이 충만(?)하여 호불호가 분명히 갈리는 소설임에는 분명합니다. 전 개인적인 취향에 맞아 굉장히 재미있게 읽었습니다. 등장인물들은 꽤 많이 등장하지만 각자의 케릭터 성이 분명하여 잘 기억에 남습니다. 탐정인 도쿠야와 그와 티키타카를 이루는 변호사 사야카는 저택섬의 인물과 닮아있습니다. 이 외에도 닮아 있는 부분들이 더 있지만 스포가 될수 있으니..직접 경험해보시면 좋을 것 같습니다. 책의 내용은 이렇습니다.",
