   "genre": "소설",
   "deep": false,
   "slug": "살인자는-천국에-있다",
   "excerpt": "“전원 사망완료. 지금부터 추리를 시작하겠습니다” 🔍🚪 앗 특수 설정 미스터리다~!! 🎩🔮 책은 약 300페이지 10개의 챕터로 나누어져 있습니다 📖✨ 하나. 닫힌 천국 // 둘. 팁 // 셋. 포로들 // 넷. 현상 // 다섯. 한가로운 시간 // 여섯. 손끝은 가리킨다 // 일곱. 모습이 없는 사람 // 여덟. 천사들의 수확 // 아홉. 소원 // 열. 끝나는 바다로 🌊☁️ 책의 주요 등장 인물은 여섯 명입니다. 각자의 케릭터성이 이름으로 나타나 상대적으로 등장 인물에 대한 헷갈림은 적은 편입니다. 🧑‍🤝‍🧑💡 전체적인 분위기는 밝음입니다. 푸른 바다, 눈부신 하늘, 여유로움이 이 책을 관통하는 분위기입니다.",
