   "deep": false,
   "slug": "세상-끝의-살인",
   "excerpt": "곧 멸망하는 세계. 그리고 그 속에서 벌어진 살인 사건🔪 운전 강사와 수강생이 그 사건을 파헤친다... (응?????) 🚗🕵️‍♀️ 책은 약 400페이지로 6장으로 나누어져 있습니다. 각 페이지당 글자수가 많아 체감은 훨씬 더 두꺼운 책으로 느껴집니다. 📖 1장 잠재적으로 위험한 금요일 2장 형제 배 3장 주모자 4장 잔류한 사람들 5장 충돌 6장 가능성을 좁혀 온 소녀 책의 주요 인물은 운전 강사 이시가와와 수강생 하루입니다. 세기말, 곧 세상이 소행성과 충돌해 멸망하는 배경입니다. 🌍☄️ 이야기는 이렇습니다... 곧 소행성 충돌로 세상이 멸망할 예정인데, 주인공 하루는 이시가와에게 운전 강습을 받고 있습니다.",
   "pages": 408,
   "pubdate": "2023-12-15",
