   "gajebon": false,
   "genre": "소설",
   "deep": false,
   "slug": "젠슈의-발소리",
   "excerpt": "히가 자매 시리즈의 5번째! 그런데..사와무라 이치는 장편이 맞는듯… 책은 약 280페이지로 4개의 단편과 1개의 중편으로 이루어져 있습니다. 1. 거울 2. 우리 마을 레이코 씨 3. 요괴는 요괴를 낳는다 4. 빨간 학생복의 소녀 5. 젠슈의 발소리 역시나 이번 작도 히가 남매 중 첫째 히가 코토코와 셋째인 히가 마코토를 중심으로 이야기가 전개 됩니다. 7남매인걸로 예상되는데 나머지 4명에 대해서는 언제 어떻게 등장 시킬지 궁금하군요. (둘째인 히가 미하루는 몇 번 나왔으니 제외하더라도..) 1 거울 –별3개- 다하라 히데키는 주말인 일요일 자명종 시계를 들으며 일어나서 결혼식장 준비를 하고 있습니다.",
