   "slug": "1961-도쿄-하우스",
   "excerpt": "다크 미스터리의 여왕인 마리 유키코의 작품입니다 신박한 소재로 이야기가 시작되는데 과연!! 책은 약 380페이지로 이루어져 있으며, 시간순으로 이야기가 전개됩니다. 이야기의 주요 시점은 이 프로그램을 기획한 다카야의 눈으로 주로 진행되고 주변 인물의 시점에서도 이야기는 전개됩니다. 이런 시점으로 인해 우리는 사건을 다양한 각도에서 보게됩니다. 이야기는 이렇습니다. G 방송국 개국 60주년을 기념하여 현대의 가족이 100년전 생활을 체험하는 컨셉을 바탕으로 리얼리티 쇼가 기획됩니다. 하지만 이 기획은 최초의 기획에서 약간은 벗어난 형태로 실제 프로그램에 편성됩니다. 장소 또한 과거에 연쇄 살인이 있었던 곳에서 말입니다.",
