   "deep": false,
   "slug": "레몬과-살인귀",
   "excerpt": "이 책은 미스터리 요소가 들어간 성장 소설이라고 볼 수 있습니다 그리고 읽는 내내 레몬의 시큼한 맛이 느껴지는 것 같군요 책은 약 340페이지로 크게 보면 2개의 장으로 나누어져 있고 각 장은 작은 챕터로 나누어져 있습니다. 책의 주요 화자는 주인공인 고바야시 미오입니다. 이 책 약간은 복잡합니다. 등장 인물들을 적어놓고 관계도를 보면서 읽으면 재미가 훨씬 커질 것 같습니다. 책의 내용은 이렇습니다. 주인공 미오의 동생 히나가 산에서 시신으로 발견되었습니다. 그리고 히나에게는 몇가지 의혹들이 있었습니다. 전 남자친구가 등산 중에 실족사를 하였고 그 남자친구의 생명 보험 수령인이 히나로 되어 있었습니다.",
