   "slug": "일이란-무엇인가",
   "excerpt": "이 책 굉장히 전형적이고 뻔한 말로 가득 차 있습니다. 하지만… 그만큼 우리가 꼭 알아야 할 내용들로 꽉꽉 차 있습니다 직장인이라면 무조건 읽어야 할 책! 책은 약 300페이지 5개의 장 33개의 작은 챕터로 이루어져 있습니다. 1장 태도경영 2장 성과경영 3장 관계경영 4장 원점경영 5장 자기경영 책의 저자는 삼성전자의 전 대표이사로 평사원에서 사장까지 올라간 입지적인 인물입니다. 삼성전자 무선사업부를 이끌면서 놀라운 업적을 많이 남겼습니다. 이 책은 그가 조직 생활을 하면서 후배들에게 받았던 질문에 대한 답과 그가 생각한 일에 대한 내용이 담겨져 있습니다. 앞서 이야기하였지만 이 책의 내용은 정말 이상적이고 당연한 이야기들입니다.",
