   "excerpt": "테스카틀리포카의 그 작가의 신작입니다 이 책 또한 놀랍군요 책은 약 420페이지 8개의 단편으로 구성되어 있습니다. 모든 단편들이 기괴하고 독특합니다. 그리고 상당한 양의 자료 수집 후 이야기를 쓰는 스타일이 신걸로 추정됩니다. (굉장히 전문적인 내용들도 많이 들어있습니다. 특히 양자 역학…) 1 폭발물 처리반이 조우한 스핀 -별3개- 교육청으로 가고시마 내 초등학교에 폭탄을 터트리겠다는 협박 전화가 걸려왔습니다 이에 우하라 경사 포함 폭발물처리반이 출동하였고 동상 뒤에 수상한 물건을 발견했습니다. 그리고 그 수상한 물건을 처리하면서 폭탄이 터졌습니다.",
