   "slug": "일곱-명의-술래잡기",
   "excerpt": "무궁화 꽃이 피었습니다~ 다~레마가 죽~였다~ 어….. 책은 약 420페이지로 각 페이지마다 글자수가 상대적으로 많아 체감 500페이지 이상입니다. 총 18개의 장과 과거의 어느 광경 5가지로 구성되어 있습니다. 호러 미스터리를 표방하고 있으며, (사실 호러 미스터리란 말은 공포가 가미된 미스터리가 맞음.. 자세한 이야기는 나중에 기회가 있다면..) 전 이 책을 밤에 혼자 읽다가 화장실에 선반이 떨어져서 그날은 불 켜고 자려는 마음을 먹은..그만큼 읽다 보면 굉장히 섬뜩한 부분이 있습니다. 이야기는 이렇습니다. 생명의 전화에서 상담원으로 일하고 있는 누마타 야예에게 이상한 전화가 걸려옵니다",
