   "genre": "소설",
   "deep": false,
   "slug": "묵시록-살인사건",
   "excerpt": "강렬한 표지, 그리고 강렬한 제목.. 그만큼 강렬한 이야기 책은 약 460페이지 8개의 챕터로 나누어져 있습니다. 1. 나비 떼 2. 화염의 십자가 3. 제4의 비극 4. 추적 5. 사도들 6. 협박 7. 북녘 들판 8. 지옥의 낙원 이 책은 강렬합니다. 특히 책에서 제가 뛰어나다고 생각하는 부분 중 하나인 영상미가 놀랍습니다. 책에서 영상미를 보여주는 부분을 의아하게 생각할 수 있는데, 강렬한 묘사로 머리에 딱 떠오르게 하는 부분들이 있습니다. 특히 범죄 장면들, 중반 이후 특정 장소에서 묘사되는 부분들 등은 글로 쓰여 있지만 머리속에 딱하고 박히는 이미지를 떠오르게 합니다.",
