   "rating": 5,
   "plus": false,
   "gajebon": false,
   "genre": "소설",
   "deep": false,
   "slug": "명탐정의-창자",
   "excerpt": "이야 좋네요 아직 덜 완성된 것 같은 느낌이지만 이 나름대로의 매력이 있습니다 흥해라~~ 책은 약 420페이지 총 4개의 단편으로 이루어져 있습니다. 1. 간노지 사건 2. 야에 사다 사건 3. 농약 콜라 사건 4. 쓰케야마 사건 이 모든 이야기는 실제 일본에서 일어난 사건들입니다. 이 사건 외에도 3개의 사건이 더 녹아들어 있습니다. 이 책은 특수 설정 미스터리 입니다. 과거에 죽은 사람이 현생에서 살아나고, 위에 언급한 사건들의 범인이 인귀가 되어 현생에 사람에 들어가고…..이렇게만 보면 “어?!?!” 라고 생각하실 수 있는데 이 부분에 미스터리 요소를 첨가하여 놀라운 이야기로 변모합니다",
