   "excerpt": "코로나 사태 속 네 개의 기묘한 수수께끼.. 코로나… 코로나… 음????? 책은 약 340페이지 4개의 단편으로 구성되어 있습니다. 1. 위험한 도박 – 사립 탐정 와카쓰키 하루미 2. ‘2021년도 입시’라는 제목의 추리 소설 3. 마트료시카의 밤 4. 6명의 격양된 마스크맨 모든 소재와 이야기의 구성이 독특합니다. 특히 2021년도 입시라는 제목의 추리 소설은 브리콜라주로 여러 텍스트를 모아서 만든 이야기입니다. 이런 파격적인 형식과 이야기는 장단점이 있습니다. 그건 뒤에서 좀 더 이야기해 보겠습니다 1.",
