   "excerpt": "📚 소설 “살육에 이르는 병”으로 우리에게 엄청난 충격을 준 아비코 다케마루가 돌아왔습니다! 하지만 이번 작품은…🤔 이 책은 약 270페이지로, 에필로그를 포함해 20개의 챕터로 구성되어 있습니다. 📖 제목에서 알 수 있듯이, 늑대(시게오)가 토끼(도모키와 고스모)를 쫓는 내용입니다. 🐺🐇 주요 화자는 주인공인 도모키의 시점으로 진행되며, 시게오의 시점도 중간중간 포함되어 있습니다. 이야기의 줄거리는 다음과 같습니다. 📚 주인공 도모키는 초등학교 5학년으로, 고스모와 친구입니다. 고스모는 가정 폭력을 당하고 있었고, 친구들과도 잘 지내지 못했지만, 도모키와는 이상하게 잘 지냈습니다.",
